; times10.asm -- chapter 9: HL x 10 with no multiplication
; generated by gen09.py
        INCLUDE "msx.inc"
        OUTPUT "times10.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
RESULTS EQU RAM_START          ; what the program found: the debugger reads it here
init:   di
        ld sp, SYS_AREA
        ld hl, 0
c0:     call times10
        ld (RESULTS+0), hl      ; HL after
        ld a, 0
        adc a, 0                ; the carry out of the last ADD HL,HL
        ld (RESULTS+2), a       
        ld hl, 1
c1:     call times10
        ld (RESULTS+4), hl      ; HL after
        ld a, 0
        adc a, 0                ; the carry out of the last ADD HL,HL
        ld (RESULTS+6), a       
        ld hl, 1234
c2:     call times10
        ld (RESULTS+8), hl      ; HL after
        ld a, 0
        adc a, 0                ; the carry out of the last ADD HL,HL
        ld (RESULTS+10), a      
        ld hl, 6553
c3:     call times10
        ld (RESULTS+12), hl     ; HL after
        ld a, 0
        adc a, 0                ; the carry out of the last ADD HL,HL
        ld (RESULTS+14), a      
        ld hl, 6554
c4:     call times10
        ld (RESULTS+16), hl     ; HL after
        ld a, 0
        adc a, 0                ; the carry out of the last ADD HL,HL
        ld (RESULTS+18), a      
stop:   jr stop

; times10: HL = HL x 10: twice, twice again, plus itself, and twice again
times10:
        ld d, h
        ld e, l                 ; DE = x
        add hl, hl              ; 2x
        add hl, hl              ; 4x
        add hl, de              ; 5x
        add hl, hl              ; 10x
        ret
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
